\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{Reactive Grasping of Novel Objects via Tactile-Visual Fusion}
\author{M.~Lindqvist, A.~Okafor, and J.~Brunner}
\date{}

\begin{document}
\maketitle

\begin{abstract}
Robots that operate in human environments must grasp objects they have
never seen before, and they must do so robustly. In this paper, we present
a reactive grasping controller that fuses wrist-mounted tactile sensing
with monocular visual feedback to recover from slip and object motion
during grasp execution. Our controller, which is based on a learned
tactile forward model and a visual servoing loop, adjusts finger
positions at 50 Hz without replanning the full grasp. We evaluate the
approach on a 7-DoF manipulator over 1200 grasp trials with 40 unseen
household objects, and it works well. Results show that tactile-visual
fusion improves the grasp success rate from 71\% to 89\% relative to a
vision-only baseline, and that the improvement is largest for deformable
and low-friction objects. These findings show that tactile feedback is
very important for robust manipulation in unstructured environments, and
we believe our approach will be useful in practice.
\end{abstract}

\end{document}
